import { neon } from '@neondatabase/serverless';

export function getDatabaseUrl() {
  if (process.env.DATABASE_URL) return process.env.DATABASE_URL;
  if (process.env.POSTGRES_URL) return process.env.POSTGRES_URL;
  if (process.env.POSTGRES_PRISMA_URL) return process.env.POSTGRES_PRISMA_URL;
  if (process.env.POSTGRES_URL_NON_POOLING) return process.env.POSTGRES_URL_NON_POOLING;

  // Scan for any variable generated by Vercel integrations
  for (const key of Object.keys(process.env)) {
    if ((key.includes('DATABASE') || key.includes('POSTGRES')) && key.includes('URL') && process.env[key]) {
      return process.env[key];
    }
  }
  return null;
}

export function getDb() {
  const databaseUrl = getDatabaseUrl();
  if (!databaseUrl) {
    throw new Error('Database connection URL is missing in Vercel. Please ensure your Neon database is connected under Vercel Storage.');
  }
  return neon(databaseUrl);
}

export async function initDb() {
  const sql = getDb();
  await sql`
    CREATE TABLE IF NOT EXISTS gallery_images (
      id SERIAL PRIMARY KEY,
      bucket VARCHAR(100) NOT NULL,
      name VARCHAR(255) NOT NULL,
      url TEXT NOT NULL,
      created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
    );
  `;
}
